param([Parameter(Mandatory=$true)][string]$RunRoot,[Parameter(Mandatory=$true)][string]$WorkingDirectory,[Parameter(Mandatory=$true)][string[]]$SourcePaths,[Parameter(Mandatory=$true)][string]$BuildManifestPath)
$ErrorActionPreference='Stop';$RunRoot=[IO.Path]::GetFullPath($RunRoot);$cwd=[IO.Path]::GetFullPath($WorkingDirectory);$env:M0_RUN_EVIDENCE_ROOT=$RunRoot;$bm=Get-Content -LiteralPath $BuildManifestPath -Raw|ConvertFrom-Json;$env:M1_FIX1_BUILD_CAPTURE_ID=[string]$bm.capture_id;$out=Join-Path $RunRoot 'test';New-Item -ItemType Directory -Path $out -Force|Out-Null
function Head{$h=& git -C $cwd rev-parse HEAD;if($LASTEXITCODE -ne 0){throw 'git rev-parse failed'};return $h.Trim()}
function Snap([string]$name){$rows=@(foreach($rel in $SourcePaths){$p=Join-Path $cwd $rel;$b=[IO.File]::ReadAllBytes($p);$lf=[Text.Encoding]::UTF8.GetBytes([Text.Encoding]::UTF8.GetString($b).Replace("`r`n","`n"));$blob=& git -C $cwd hash-object -- $rel;if($LASTEXITCODE -ne 0){throw 'git hash-object failed'};[pscustomobject]@{path=$rel;size=$b.Length;sha256=([Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($b)).ToLowerInvariant());lf_sha256=([Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($lf)).ToLowerInvariant());git_blob=$blob.Trim()}});$rows|ConvertTo-Json -Depth 4|Set-Content -LiteralPath (Join-Path $out "$name-source.json") -Encoding utf8;return ,$rows}
$started=[DateTime]::UtcNow.ToString('o');$headBefore=Head;$before=Snap 'before';$psi=[Diagnostics.ProcessStartInfo]::new('cmd.exe');$psi.WorkingDirectory=$cwd;$psi.UseShellExecute=$false;$psi.RedirectStandardOutput=$true;$psi.RedirectStandardError=$true;foreach($a in @('/d','/c','npm.cmd test -- --reporter=verbose acceptance-tests/snapshot-recovery.test.ts')){$psi.ArgumentList.Add($a)};$proc=[Diagnostics.Process]::Start($psi);$ot=$proc.StandardOutput.ReadToEndAsync();$et=$proc.StandardError.ReadToEndAsync();$proc.WaitForExit();$exit=$proc.ExitCode;$stdout=$ot.GetAwaiter().GetResult();$stderr=$et.GetAwaiter().GetResult();[IO.File]::WriteAllText((Join-Path $out 'stdout.txt'),$stdout,[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $out 'stderr.txt'),$stderr,[Text.UTF8Encoding]::new($false));$after=Snap 'after';$headAfter=Head;$finished=[DateTime]::UtcNow.ToString('o');$record=[ordered]@{kind='Test';capture_id=(Split-Path -Leaf $RunRoot);build_capture_id=$bm.capture_id;build_manifest_path=[IO.Path]::GetFullPath($BuildManifestPath);build_manifest_sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath $BuildManifestPath).Hash.ToLowerInvariant();cwd=$cwd;evidence_root=$RunRoot;command='npm.cmd test -- --reporter=verbose acceptance-tests/snapshot-recovery.test.ts';started_utc=$started;finished_utc=$finished;actual_head_before=$headBefore;actual_head_after=$headAfter;exit_code=$exit;stdout=(Join-Path $out 'stdout.txt');stderr=(Join-Path $out 'stderr.txt')};$record|ConvertTo-Json -Depth 6|Set-Content -LiteralPath (Join-Path $out 'command.json') -Encoding utf8;"CAPTURED test build_id=$($bm.capture_id) exit=$exit HEAD=$headBefore";Get-Content -LiteralPath (Join-Path $out 'stdout.txt');if($stderr){[Console]::Error.WriteLine($stderr)};exit $exit
